 juce::Graphics::ScopedSaveState save(g);g.addTransform(juce::AffineTransform::scale(area.getWidth()/604,area.getHeight()/292).translated(area.getX(),area.getY()));
 const juce::Colour blue(0xff3e6696),ochre(0xff927135),grey(0xff5c6c75),red(0xffff0800),white(0xffcbd3bf),purple(0xff64254f),dim(0xff373e42);const std::array<juce::Colour,4> colours{{blue,ochre,grey,red}};
 g.setColour(juce::Colours::black);g.fillRect(0,0,604,292);
