 auto arrow=[&](float x,float y,float xx,float yy,juce::Colour c){line(x,y,xx,yy,c);const float angle=std::atan2(yy-y,xx-x);juce::Path p;p.startNewSubPath(xx,yy);p.lineTo(xx-11*std::cos(angle-.45f),yy-11*std::sin(angle-.45f));p.lineTo(xx-11*std::cos(angle+.45f),yy-11*std::sin(angle+.45f));p.closeSubPath();g.setColour(c);g.fillPath(p);};
 auto module=[&](int group,float x,float y){g.setColour(grey);g.fillRoundedRectangle(x,y,70,70,12);g.setColour(white);juce::Path p;if(group==0){for(int i=0;i<48;++i){float xx=x+11+i,yy=y+35-std::sin(i*juce::MathConstants<float>::twoPi/16)*12;if(i==0)p.startNewSubPath(xx,yy);else p.lineTo(xx,yy);}g.strokePath(p,juce::PathStrokeType(2.5f));}else if(group==1){p.startNewSubPath(x+11,y+48);p.lineTo(x+26,y+20);p.lineTo(x+38,y+35);p.lineTo(x+49,y+35);p.lineTo(x+60,y+49);g.strokePath(p,juce::PathStrokeType(2.4f));}else text(group==2?"FX":"OUT",x+6,y+17,58,37,28,white);};
 auto keyboard=[&](float x,float y,const juce::String& label){g.setColour(juce::Colour(0xff3c392e));g.fillRoundedRectangle(x,y,70,70,10);for(int i=0;i<7;++i){g.setColour(white);g.fillRect(x+12+i*7,y+18,5.f,33.f);if(i!=2&&i!=6){g.setColour(juce::Colours::black);g.fillRect(x+16+i*7,y+18,4.f,20.f);}}text(label,x-18,y+77,106,24,18,grey);};
 auto amount=[&](float value,float x,float y,juce::Colour c){juce::Path box;box.startNewSubPath(x,y);box.lineTo(x+82,y);box.lineTo(x+96,y+13);box.lineTo(x+96,y+70);box.lineTo(x,y+70);box.closeSubPath();g.setColour(c.withAlpha(.5f));g.strokePath(box,juce::PathStrokeType(1.6f));text(juce::String(value*100,0),x+3,y+1,88,66,43,c);};
 auto knob=[&](float x,float y,int parameter){g.setColour(purple);g.drawRoundedRectangle(x,y,70,70,13,1.7f);g.setColour(white.darker(.35f));g.fillEllipse(x+15,y+28,42,31);g.setColour(grey.brighter(.35f));g.fillEllipse(x+19,y+14,34,38);g.setColour(colours[(size_t)(parameter%4)]);g.fillEllipse(x+23,y+10,26,22);g.setColour(white.withAlpha(.5f));g.drawEllipse(x+23,y+10,26,22,1);text("SHIFT",x+9,y+58,52,15,12,purple.brighter(.4f));};
 auto speaker=[&](float x,float y){g.setColour(juce::Colours::black);g.drawRect(x,y+9,11.f,17.f,2.f);juce::Path p;p.startNewSubPath(x+11,y+9);p.lineTo(x+23,y);p.lineTo(x+23,y+35);p.lineTo(x+11,y+26);g.strokePath(p,juce::PathStrokeType(2));for(int i=0;i<3;++i){juce::Path wave;wave.startNewSubPath(x+29+i*6,y+5-i*4);wave.quadraticTo(x+37+i*7,y+17,x+29+i*6,y+30+i*4);g.strokePath(wave,juce::PathStrokeType(2));}};
 auto envelope=[&](float x,float y){g.setColour(purple);g.drawRoundedRectangle(x,y,70,70,12,1.5f);const float v=s.envelope;juce::Path p;p.startNewSubPath(x+11,y+56);if(std::abs(v)<.001f)p.lineTo(x+60,y+11);else if(v>=0)p.quadraticTo(x+25,y+55-40*(1-v),x+60,y+11);else{p.clear();p.startNewSubPath(x+11,y+11);p.quadraticTo(x+25,y+50+v*30,x+60,y+56);}g.setColour(red);g.strokePath(p,juce::PathStrokeType(2));};
